import{_ as e,o as t,c as r,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Scratch-Variables.md","filePath":"manual-zh/Scratch-Variables.md","lastUpdated":1785684581000}'),o={name:"manual-zh/Scratch-Variables.md"};function d(s,a,_,n,l,i){return t(),r("div",null,[...a[0]||(a[0]=[c('<h4 id="_6-7-5-暂用变量" tabindex="-1">6.7.5 暂用变量 <a class="header-anchor" href="#_6-7-5-暂用变量" aria-label="Permalink to &quot;6.7.5 暂用变量&quot;">​</a></h4><p>大多数情况下，变量不会在个案之间保留其值。相反，要么它们正从数据文件或活动数据集中读取（此时它们取所读取的值），要么如果是用 <code>COMPUTE</code> 或其他转换创建的，则会根据类型初始化为系统缺失值或空格。</p><p>不过，有时拥有一个能在个案之间保留其值的变量会很有用。你可以用 <code>LEAVE</code>（参见 <a href="./LEAVE">LEAVE</a>）做到这一点，也可以使用<em>暂用变量</em>。暂用变量是名称以井号（‘#’）开头的变量。</p><p>暂用变量与用 <code>LEAVE</code> 保留的变量具有相同的属性：它们在个案之间保留其值，并且对第一个个案初始化为 0 或空格。它们还有一个额外属性，即在任何过程执行之前被删除。因此，暂用变量不能用于分析。若要在分析中使用暂用变量，请使用 <code>COMPUTE</code>（参见 <a href="./COMPUTE">COMPUTE</a>）将其值复制到一个普通变量，然后在该分析中使用那个普通变量。</p>',4)])])}const m=e(o,[["render",d]]);export{h as __pageData,m as default};
